SELECT id, client_msg_id, conversation_id, sender_id, content, msg_type, created_at,
       recalled_at, quote_message_id
FROM im_message
WHERE conversation_id = #{conversationId}
  AND sender_id = #{senderId}
  AND client_msg_id = #{clientMsgId}

SELECT id, client_msg_id, conversation_id, sender_id, content, msg_type, created_at,
       recalled_at, quote_message_id
FROM im_message
WHERE conversation_id = #{conversationId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT


WHERE m.conversation_id = #{conversationId}
  AND m.id > #{afterId}
  AND NOT EXISTS (
      SELECT 1 FROM im_message_hidden h
      WHERE h.user_id = #{userId} AND h.message_id = m.id
  )
ORDER BY m.id ASC
LIMIT #{limit}

SELECT


WHERE m.conversation_id = #{conversationId}
  AND m.id < #{beforeId}
  AND NOT EXISTS (
      SELECT 1 FROM im_message_hidden h
      WHERE h.user_id = #{userId} AND h.message_id = m.id
  )
ORDER BY m.id DESC
LIMIT #{limit}

SELECT


WHERE m.conversation_id = #{conversationId}
  AND NOT EXISTS (
      SELECT 1 FROM im_message_hidden h
      WHERE h.user_id = #{userId} AND h.message_id = m.id
  )
ORDER BY m.id DESC
LIMIT #{limit}

